// js
if (get(ctx.subject.employment, 'terms.work_classification', '') === 'NON_EA') return false;
return get(ctx.subject.employment, 'engagement', 'EMPLOYEE') !== 'PART_TIME';

conversion:
// js
// MOM and EA Fourth Schedule: a monthly rate's hourly basic rate is 12 × monthly ÷ (52 × 44) whatever the contract's week, so not the day ÷ its hours; a daily rate's is the day ÷ its hours
const terms = ctx.subject.employment.terms;
const normal = Number(get(terms, 'normal_hours_per_day', 8));
const hourly =
	get(terms, 'rate.unit', 'MONTHLY') === 'MONTHLY'
		? (Number(get(terms, 'rate.amount', 0)) * ctx.lookup.months_per_year) /
			(ctx.lookup.weeks_per_year * ctx.lookup.full_time_weekly_hours)
		: ctx.day_rate / normal;
const category = get(terms, 'statutory_work_category', 'NON_MANUAL');
const capped = category === 'NON_MANUAL' ? Math.min(hourly, ctx.lookup.non_workman_hourly_cap) : hourly;
// a rest day's normal hours are rest-day pay; only the hours past them are overtime
const hours = sum(
	get(ctx, 'work.days', []).map((day) => {
		if (get(day, 'day_type', 'WORK') !== 'REST') return Number(get(day, 'overtime_hours', 0));
		return Math.max(0, Number(get(day, 'worked_hours', 0)) - normal);
	})
);
return hours * capped * ctx.lookup.multiplier;

eligibility:
// js
if (get(ctx.subject.employment, 'terms.work_classification', '') === 'NON_EA') return false;
return ctx.subject.employment.engagement === 'PART_TIME';

conversion:
// js
// Part-Time Regulations: hourly basic rate on the contract's own week; hours to the full-time day at 1×, past it at 1.5×
const employment = ctx.subject.employment;
const terms = employment.terms;
const normal = Number(get(terms, 'normal_hours_per_day', 8));
const full = Number(get(employment, 'employee_extension_data.term_facts.comparable_full_time_hours_per_day', 8));
const tier = Math.max(0, full - normal);
const hourly =
	get(terms, 'rate.unit', 'MONTHLY') === 'MONTHLY'
		? (Number(get(terms, 'rate.amount', 0)) * ctx.lookup.months_per_year) /
			(ctx.lookup.weeks_per_year * Number(get(terms, 'normal_hours_per_week', ctx.lookup.full_time_weekly_hours)))
		: ctx.day_rate / normal;
const hours = sum(
	get(ctx, 'work.days', [])
		.filter((day) => (get(day, 'day_type', 'WORK') === 'REST') === ctx.lookup.rest_day)
		.map((day) => {
			const beyond = ctx.lookup.rest_day
				? Math.max(0, Number(get(day, 'worked_hours', 0)) - normal)
				: Number(get(day, 'overtime_hours', 0));
			return ctx.lookup.past_full_time ? Math.max(0, beyond - tier) : Math.min(beyond, tier);
		})
);
return hours * hourly * ctx.lookup.multiplier;

