// js
// EA s.37, at the employer's request: one day's salary up to half the normal hours, two above half
const normal = Number(get(ctx.subject.employment.terms, 'normal_hours_per_day', 8));
const days = sum(
	get(ctx, 'work.days', [])
		.filter((day) => get(day, 'day_type', 'WORK') === 'REST' && Number(get(day, 'worked_hours', 0)) > 0)
		.map((day) =>
			Number(get(day, 'worked_hours', 0)) <= normal / ctx.lookup.half_day_divisor
				? ctx.lookup.employer_request_days_up_to_half
				: ctx.lookup.employer_request_days_above_half
		)
);
return days * ctx.day_rate;

